586	// RegisterCandidate 在当前轮次本地提议已产生且尚未确认时，按给定交易顺序登记一个
587	// 竞争候选，与本地提议一起参与投票。候选使用当前轮次与下一高度，接在最新确认块之后。
588	//
589	// 候选只能包含当前池内排队或已提议的交易，数量不得超过单块上限，允许空块；
590	// 列表不能重复交易；每个账户在列表中的序号必须从该账户已确认序号加一开始连续递增，
591	// 不同账户之间的顺序由调用者决定。相同列表重复登记返回同一候选并保留已有票数。
592	//
593	// 未产生本地提议、轮次不是当前轮次、引用未知或已退出池的交易、超过上限或序号
594	// 不连续时登记失败并返回带具体 Reason 的 *RejectError，节点状态不变。
595	func (n *Node) RegisterCandidate(round uint64, txIDs []string) (*RegisterResult, error) {
596		n.mu.Lock()
597		defer n.mu.Unlock()
598	
599		rs := n.st.currentRoundState()
600		// 轮次优先判定：非当前轮次不能登记，即使当前轮次尚未产生本地提议。
601		if round != n.st.Round {
602			return nil, reject(ReasonWrongRound, "candidate round %d does not match current round %d", round, n.st.Round)
603		}
604		if rs == nil || rs.LocalBlockID == "" {
605			return nil, reject(ReasonNoProposal, "round %d has no local proposal yet", n.st.Round)
606		}
607	
608		ids := append([]string{}, txIDs...)
609		if uint64(len(ids)) > n.st.MaxTxs {
610			return nil, reject(ReasonTooManyTxs, "candidate contains %d transactions, max per block is %d", len(ids), n.st.MaxTxs)
611		}
612		// 列表内不得重复交易。
613		seen := make(map[string]struct{}, len(ids))
614		for _, id := range ids {
615			if _, dup := seen[id]; dup {
616				return nil, reject(ReasonDuplicateInList, "transaction %s appears more than once in candidate list", id)
617			}
618			seen[id] = struct{}{}
619			e, ok := n.st.Entries[id]
620			if !ok {
621				return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
622			}
623			// 必须仍在池中（排队或已被某未决候选引用）；已确认、被替换、已过期均已退出池。
624			if e.Status != stQueued && e.Status != stProposed {
625				return nil, reject(ReasonTxNotInPool, "transaction %s is not queued or proposed (status %s)", id, e.Status)
626			}
627			if !inPool(n.st, e.Tx.SenderHex(), e.Tx.Sequence, id) {
628				return nil, reject(ReasonTxNotInPool, "transaction %s has left the pool", id)
629			}
630		}
631		// 每个账户的序号必须从已确认序号加一开始连续递增。
632		seqsBySender := map[string][]uint64{}
633		for _, id := range ids {
634			e := n.st.Entries[id]
635			sender := e.Tx.SenderHex()
636			seqsBySender[sender] = append(seqsBySender[sender], e.Tx.Sequence)
637		}
638		senders := make([]string, 0, len(seqsBySender))
639		for sender := range seqsBySender {
640			senders = append(senders, sender)
641		}
642		sort.Strings(senders)
643		for _, sender := range senders {
644			seqs := seqsBySender[sender]
645			want := n.st.Accounts[sender] + 1
646			for i, seq := range seqs {
647				if seq != want {
648					return nil, reject(ReasonSequenceGap,
649						"sender %s candidate sequence at position %d is %d, want %d (must be consecutive starting at confirmed sequence + 1)",
650						sender, i, seq, want)
651				}
652				want++
653			}
654		}
655	
656		blockID := BlockID(rs.Round, rs.Height, rs.PreviousID, ids)
657		if existing, ok := rs.Candidates[blockID]; ok {
658			// 相同列表重复登记：返回同一候选，保留已有票数，节点状态不变。
659			return &RegisterResult{BlockID: existing.BlockID, Existing: true}, nil
660		}
661	
662		st := n.st.clone()
663		rs2 := st.Rounds[st.Round]
664		rs2.Candidates[blockID] = &candidateState{
665			TxIDs:   ids,
666			BlockID: blockID,
667			Votes:   []string{},
668		}
669		for _, id := range ids {
670			if st.Entries[id].Status == stQueued {
671				st.Entries[id].Status = stProposed
672			}
673		}
674		if err := n.save(st); err != nil {
675			return nil, err
676		}
677		n.st = st
678		return &RegisterResult{BlockID: blockID}, nil
679	}
680	
681	// inPool 判断标识 id 是否仍是池中某账户某序号的当前交易。
682	func inPool(st *state, sender string, seq uint64, id string) bool {
683		cur, ok := st.Pool[sender][seq]
684		return ok && cur == id
685	}
686	
687	// selectTransactions 执行确定性打包：
688	// 每轮从各账户“下一条可确认”的交易中选费用最高者，费用相同按交易标识字典序；
689	// 选入某账户后才继续考虑其后续序号，直到达到上限或没有可选交易。
690	func (n *state) selectTransactions() []string {
691		var picked []string
692		// 每个账户在本次打包中下一个可考虑的序号。
693		next := map[string]uint64{}
694		for sender := range n.Pool {
695			next[sender] = n.Accounts[sender] + 1
696		}
697		for uint64(len(picked)) < n.MaxTxs {
698			var bestID string
699			var bestFee uint64
700			var bestSet bool
701			// 遍历发送者名单需确定序：按发送者十六进制定序，保证选择只取决于费用与标识。
702			senders := make([]string, 0, len(n.Pool))
703			for s := range n.Pool {
704				senders = append(senders, s)
705			}
706			sort.Strings(senders)
707			for _, sender := range senders {
708				id, ok := n.Pool[sender][next[sender]]
709				if !ok {
710					continue
711				}
712				e := n.Entries[id]
713				if e.Status != stQueued {
714					continue
715				}
716				if !bestSet || e.Tx.Fee > bestFee || (e.Tx.Fee == bestFee && id < bestID) {
717					bestID = id
718					bestFee = e.Tx.Fee
719					bestSet = true
720				}
721			}
722			if !bestSet {
723				break
724			}
725			picked = append(picked, bestID)
726			next[n.Entries[bestID].Tx.SenderHex()]++
727		}
728		if picked == nil {
729			picked = []string{}
730		}
731		return picked
732	}
733	
734	// VoteResult 是投票处理结果。
735	type VoteResult struct {
736		// Counted 本次投票是否新计入票数（重复投同一候选为 false）。
737		Counted bool
738		// Confirmed 本次投票是否令某候选立即确认。
739		Confirmed bool
740		// Block 确认时为新区块；否则为 nil。
741		Block *Block
742	}
743	
744	// Vote 处理验证者对当前轮次某已登记候选的投票。
745	// 每位验证者一轮内只能选择一个候选：重复投同一候选不增加票数但不报错；
746	// 改投其他候选明确拒绝（ReasonAlreadyVoted），原票保留。
747	// 票数严格超过名单人数三分之二时立即确认该候选，其他候选落选并进入下一轮。
748	// 名单外身份、错误轮次、未知区块标识返回带具体 Reason 的 *RejectError。
749	func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
750		n.mu.Lock()
751		defer n.mu.Unlock()
752	
753		key := fmt.Sprintf("%x", validator)
754		allowed := false
755		for _, v := range n.st.Validators {
756			if fmt.Sprintf("%x", v) == key {
757				allowed = true
758				break
759			}
760		}
761		if !allowed {
762			return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
763		}
764		rs := n.st.currentRoundState()
765		// 轮次优先判定：旧轮次投票不能影响新轮次，即使新轮次尚未产生本地提议。
766		if rs == nil || rs.LocalBlockID == "" {
767			if round != n.st.Round {
768				return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
769			}
770			return nil, reject(ReasonNoProposal, "round %d has no proposal", n.st.Round)
771		}
772		if round != rs.Round {
773			return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, rs.Round)
774		}
775		if _, ok := rs.Candidates[blockID]; !ok {
776			return nil, reject(ReasonWrongBlock, "block id %s is not a registered candidate in round %d", blockID, rs.Round)
777		}
778	
779		// 每位验证者一轮内只能选择一个候选。
780		for id, cand := range rs.Candidates {
781			for _, vk := range cand.Votes {
782				if vk == key {
783					if id == blockID {
784						return &VoteResult{Counted: false}, nil // 重复投同一候选不增票
785					}
786					return nil, reject(ReasonAlreadyVoted,
787						"validator %s already voted for candidate %s in round %d and cannot switch to %s", key, id, rs.Round, blockID)
788				}
789			}
790		}
791	
792		st := n.st.clone()
793		rs2 := st.Rounds[st.Round]
794		cand := rs2.Candidates[blockID]
795		cand.Votes = append(cand.Votes, key)
796		sort.Strings(cand.Votes)
797	
798		res := &VoteResult{Counted: true}
799		threshold := len(st.Validators) * 2 / 3
800		if len(cand.Votes) > threshold {
801			block := st.resolveRound(cand.BlockID, true)
802			res.Confirmed = true
803			// 返回独立快照，调用方改写 res.Block 不会触及已保存进 st 的确认块。
804			snap := copyBlock(&block)
805			res.Block = &snap
806		}
807		if err := n.save(st); err != nil {
808			return nil, err
809		}
810		n.st = st
811		return res, nil
812	}
813	
814	// resolveRound 在内存状态上完整应用一轮的决出：
815	// confirm 为 true 时胜出候选按其交易顺序生成连续高度的确认块，随后胜出与落选
816	// 候选中引用的交易分别按规则处理（确认一次 / 回到排队），最后进入下一轮并使
817	// 到期交易失效。confirm 为 false（EndRound）时不生成确认块，所有候选引用的
818	// 交易全部回到排队。调用方随后通过一次原子保存落盘。
819	func (s *state) resolveRound(winnerID string, confirm bool) Block {
820		rs := s.Rounds[s.Round]
821		var block Block
822		winnerTx := map[string]struct{}{}
823		if confirm {
824			winner := rs.Candidates[winnerID]
825			height := uint64(len(s.Blocks)) + 1
826			// 历史中保存的是胜出候选交易列表的独立副本：调用方对 Vote 返回块的
827			// 改写（交换顺序、改标识、增减长度）不会触及确认历史，也不会随后续保存落盘。
828			txIDs := append([]string{}, winner.TxIDs...)
829			if txIDs == nil {
830				txIDs = []string{}
831			}
832			block = Block{
833				Height:     height,
834				Round:      rs.Round,
835				ID:         winner.BlockID,
836				PreviousID: s.LastBlock,
837				TxIDs:      txIDs,
838			}
839			for _, id := range block.TxIDs {
840				winnerTx[id] = struct{}{}
841				e := s.Entries[id]
842				sender := e.Tx.SenderHex()
843				// 候选校验保证序号从已确认序号加一起连续递增。
844				s.Accounts[sender] = e.Tx.Sequence
845				delete(s.Pool[sender], e.Tx.Sequence)
846				if len(s.Pool[sender]) == 0 {
847					delete(s.Pool, sender)
848				}
849				e.Status = stConfirmed
850				e.ReplacedBy = ""
851				s.Confirmed[id] = confirmedRef{Height: height, Block: block.ID}
852			}
853			s.Blocks = append(s.Blocks, block)
854			s.LastBlock = block.ID
855		}
856		// 标记全部候选的胜出/落选结果；只有未在胜出块中的交易才回到排队。
857		// 被多个候选共享的胜出交易只确认一次，落选候选不能再改变其状态。
858		for id, cand := range rs.Candidates {
859			cand.Decided = true
860			cand.Winner = confirm && id == winnerID
861			if !cand.Winner {
862				for _, txID := range cand.TxIDs {
863					if _, won := winnerTx[txID]; won {
864						continue
865					}
866					if e, ok := s.Entries[txID]; ok && e.Status == stProposed {
867						e.Status = stQueued
868					}
869				}
870			}
871		}
872		rs.Ended = true
873		rs.EndedByConfirm = confirm
874		s.Round++
875		s.expire()
876		return block
877	}
878	
879	// expire 使池内到期轮次不大于当前轮次的交易失效。轮次已决出，池中剩余的
880	// 均为排队交易（落选候选独有或从未被引用）。
881	func (s *state) expire() {
882		for sender, seqs := range s.Pool {
883			for seq, id := range seqs {
884				e := s.Entries[id]
885				if e.Tx.Expiry <= s.Round {
886					e.Status = stExpired
887					delete(seqs, seq)
888				}
889			}
890			if len(seqs) == 0 {
891				delete(s.Pool, sender)
892			}
893		}
894	}
895	
896	// EndRound 主动结束当前未确认轮次：所有候选落选且不生成确认块，
897	// 候选中的交易按落选规则回到排队状态，随后进入下一轮并使到期交易失效。
898	// 旧轮次投票随候选结果一并保留在历史中，但不能影响新轮次。
899	func (n *Node) EndRound() (uint64, error) {
900		n.mu.Lock()
901		defer n.mu.Unlock()
902		st := n.st.clone()
903		rs := st.Rounds[st.Round]
904		if rs == nil {
905			// 本轮尚未产生本地提议：仍允许直接结束，空轮留作未确认结束记录。
906			rs = &roundState{
907				Round:      st.Round,
908				Height:     uint64(len(st.Blocks)) + 1,
909				PreviousID: st.LastBlock,
910				Candidates: map[string]*candidateState{},
911			}
912			st.Rounds[st.Round] = rs
913		}
914		st.resolveRound("", false)
915		if err := n.save(st); err != nil {
916			return 0, err
917		}
918		n.st = st
919		return st.Round, nil
920	}
921	
922	// Height 返回已确认区块数（最新高度）。
923	func (n *Node) Height() uint64 {
924		n.mu.Lock()
925		defer n.mu.Unlock()
926		return uint64(len(n.st.Blocks))
927	}
928	
929	// BlockAt 按连续高度查询确认块，高度从 1 开始。
930	func (n *Node) BlockAt(height uint64) (Block, error) {
931		n.mu.Lock()
932		defer n.mu.Unlock()
933		if height == 0 || height > uint64(len(n.st.Blocks)) {
934			return Block{}, reject(ReasonUnknownBlock, "block at height %d does not exist", height)
935		}
936		return copyBlock(&n.st.Blocks[height-1]), nil
937	}
938	
939	// LatestBlock 返回最新确认块；尚无确认块时第二返回值为 false。
940	// 返回的是取得时的独立快照，调用方改写不影响节点内的确认历史。
941	func (n *Node) LatestBlock() (Block, bool) {
942		n.mu.Lock()
943		defer n.mu.Unlock()
944		if len(n.st.Blocks) == 0 {
945			return Block{}, false
946		}
947		return copyBlock(&n.st.Blocks[len(n.st.Blocks)-1]), true
948	}
949	
950	// 候选结果取值。
951	const (
952		// CandidatePending 候选尚未决出，仍可接受投票。
953		CandidatePending = "pending"
954		// CandidateWon 候选胜出，其交易已确认。
955		CandidateWon = "won"
956		// CandidateLost 轮次已结束且该候选落选。
957		CandidateLost = "lost"
958	)
959	
960	// RoundCandidates 是某一轮候选情况的只读视图。返回内容均为副本，
961	// 调用方修改切片或字节不会影响节点内部状态。
962	type RoundCandidates struct {
963		// Round 查询的轮次。
964		Round uint64
965		// Candidates 本轮全部候选，按区块标识字典序排列。
966		Candidates []CandidateView
967		// Unvoted 本轮尚未投票的验证者公钥，按公钥字典序排列。
968		Unvoted [][]byte
969		// Ended 本轮是否已经决出（确认或主动结束）。
970		Ended bool
971		// UnconfirmedEnd 为 true 表示本轮由 EndRound 主动结束、未产生确认块。
972		UnconfirmedEnd bool
973		// HasRecords 为 false 表示旧版本状态未保存该轮候选详情；
974		// 此时 Candidates 为空且不代表“该轮没有候选”。
975		HasRecords bool
976	}
977	
978	// Candidates 按轮次查看候选：列出每个候选的交易顺序、投票者（按公钥排序）
979	// 及未决/胜出/落选结果，并列出本轮尚未投票的验证者。旧轮记录保留可查；
980	// 轮次为 0 或尚未到达时返回 ReasonUnknownRound。
981	//
982	// 候选按区块标识排序，身份按公钥排序。主动结束的轮次 UnconfirmedEnd 为 true。
983	// 过去没有保存候选详情的旧轮 HasRecords 为 false。
984	func (n *Node) Candidates(round uint64) (*RoundCandidates, error) {
985		n.mu.Lock()
986		defer n.mu.Unlock()
987		// 轮次 0、尚未到达的未来轮次以及尚未产生本地提议的当前轮次均无记录。
988		// 历史轮次（含旧版本迁移轮）与未决当前轮一定有条目。
989		rs := n.st.Rounds[round]
990		if round == 0 || rs == nil {
991			return nil, reject(ReasonUnknownRound, "round %d does not exist (current round %d)", round, n.st.Round)
992		}
993		view := &RoundCandidates{
994			Round:          round,
995			Candidates:     []CandidateView{},
996			Unvoted:        [][]byte{},
997			Ended:          rs.Ended,
998			UnconfirmedEnd: rs.Ended && !rs.EndedByConfirm,
999			HasRecords:     !rs.DetailMissing,
1000		}
1001		if !rs.DetailMissing {
1002			ids := make([]string, 0, len(rs.Candidates))
1003			for id := range rs.Candidates {
1004				ids = append(ids, id)
1005			}
1006			sort.Strings(ids)
1007			voted := map[string]struct{}{}
1008			for _, id := range ids {
1009				c := rs.Candidates[id]
1010				voters := make([][]byte, 0, len(c.Votes))
1011				for _, vk := range c.Votes {
1012					pub, err := hexDecode(vk)
1013					if err != nil {
1014						return nil, fmt.Errorf("corrupt voter key %q: %w", vk, err)
1015					}
1016					voters = append(voters, pub)
1017					voted[vk] = struct{}{}
1018				}
1019				result := CandidatePending
1020				if c.Decided {
1021					if c.Winner {
1022						result = CandidateWon
1023					} else {
1024						result = CandidateLost
1025					}
1026				}
1027				view.Candidates = append(view.Candidates, CandidateView{
1028					Round:   rs.Round,
1029					BlockID: c.BlockID,
1030					TxIDs:   append([]string(nil), c.TxIDs...),
1031					Local:   c.Local,
1032					Voters:  voters,
1033					Result:  result,
1034				})
1035			}
1036			valKeys := make([]string, 0, len(n.st.Validators))
1037			for _, v := range n.st.Validators {
1038				k := fmt.Sprintf("%x", v)
1039				if _, ok := voted[k]; !ok {
1040					valKeys = append(valKeys, k)
1041				}
1042			}
1043			sort.Strings(valKeys)
1044			for _, k := range valKeys {
1045				pub, err := hexDecode(k)
1046				if err != nil {
1047					return nil, fmt.Errorf("corrupt validator key %q: %w", k, err)
1048				}
1049				view.Unvoted = append(view.Unvoted, pub)
1050			}
1051		}
1052		return view, nil
1053	}
1054	
1055	// hexDecode 解码十六进制公钥，非法输入返回错误。
1056	func hexDecode(h string) ([]byte, error) {
1057		return hex.DecodeString(h)
1058	}
1059	
1060	// Tx 按交易标识查询其状态并关联区块或替代交易。
1061	func (n *Node) Tx(id string) (*TxInfo, error) {
1062		n.mu.Lock()
1063		defer n.mu.Unlock()
1064		if e, ok := n.st.Entries[id]; ok {
1065			info := &TxInfo{
1066				ID:         id,
1067				Status:     TxStatus(e.Status),
1068				Tx:         copyTx(e.Tx),
1069				ReplacedBy: e.ReplacedBy,
1070			}
1071			if e.Status == stConfirmed {
1072				if ref, ok := n.st.Confirmed[id]; ok {
1073					info.BlockHeight = ref.Height
1074					info.BlockID = ref.Block
1075				}
1076			}
1077			if e.Status == stDropped {
1078				info.DropReason = e.DropReason
1079				info.DropRound = e.DropRound
1080			}
1081			return info, nil
1082		}
1083		return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
1084	}
1085	
1086	// Account 按发送者公钥查询已确认序号与全部待处理交易。
1087	// 因序号缺口等待时 Gap 给出最早缺少的序号；
1088	// 已提议交易显示等待投票，其余池内交易显示等待打包。
1089	func (n *Node) Account(sender []byte) *AccountInfo {
1090		n.mu.Lock()
1091		defer n.mu.Unlock()
1092		key := fmt.Sprintf("%x", sender)
1093		info := &AccountInfo{
1094			Sender:            key,
1095			ConfirmedSequence: n.st.Accounts[key],
1096			Pending:           []*TxInfo{},
1097		}
1098		seqs := n.st.Pool[key]
1099		if len(seqs) == 0 {
1100			return info
1101		}
1102		seqList := make([]uint64, 0, len(seqs))
1103		for seq := range seqs {
1104			seqList = append(seqList, seq)
1105		}
1106		sort.Slice(seqList, func(i, j int) bool { return seqList[i] < seqList[j] })
1107		expected := info.ConfirmedSequence + 1
1108		var gap uint64
1109		for _, seq := range seqList {
1110			if gap == 0 {
1111				if seq == expected {
1112					expected++
1113				} else if seq > expected {
1114					gap = expected
1115				}
1116			}
1117			id := seqs[seq]
1118			e := n.st.Entries[id]
1119			txInfo := &TxInfo{
1120				ID:     id,
1121				Status: TxStatus(e.Status),
1122				Tx:     copyTx(e.Tx),
1123			}
1124			if e.Status == stProposed {
1125				txInfo.Note = "waiting-vote"
1126			} else {
1127				txInfo.Note = "waiting-pack"
1128			}
1129			info.Pending = append(info.Pending, txInfo)
1130		}
1131		info.Gap = gap
1132		return info
1133	}
1134	
1135	func copyTx(tx *Transaction) *Transaction {
1136		if tx == nil {
1137			return nil
1138		}
1139		c := *tx
1140		c.Sender = append([]byte(nil), tx.Sender...)
1141		c.Content = append([]byte(nil), tx.Content...)
1142		c.Signature = append([]byte(nil), tx.Signature...)
1143		return &c
1144	}
1145	
1146	// copyBlock 返回确认块的独立快照：高度、轮次、区块标识、前块标识复制为值，
1147	// 交易列表使用独立切片。调用方交换顺序、改写标识或增减长度都只影响手中的结果，
1148	// 既不会污染节点内的确认历史，也不会随后续保存写入磁盘。空块保留零长度切片。
1149	func copyBlock(b *Block) Block {
1150		txIDs := append([]string{}, b.TxIDs...)
1151		if txIDs == nil {
1152			txIDs = []string{}
1153		}
1154		return Block{
1155			Height:     b.Height,
1156			Round:      b.Round,
1157			ID:         b.ID,
1158			PreviousID: b.PreviousID,
1159			TxIDs:      txIDs,
1160		}
1161	}
1162

